@Injectable()
export class AtraccionesSeed implements OnApplicationBootstrap {
  private readonly logger = new Logger(AtraccionesSeed.name);

  constructor(
    @InjectRepository(Atraccion) private readonly atracciones: Repository<Atraccion>,
    @InjectRepository(Ciudad) private readonly ciudades: Repository<Ciudad>,
    @InjectRepository(Operador) private readonly operadores: Repository<Operador>,
  ) {}

  async onApplicationBootstrap() {
    // Las ubicaciones dependen de las ciudades: se aseguran primero (no duplica nada).
    await this.ciudades.createQueryBuilder().insert().into(Ciudad).values(CIUDADES_ECUADOR).orIgnore().execute();
    await this.operadores.createQueryBuilder().insert().into(Operador).values(OPERADORES_SEED).orIgnore().execute();

    let nuevas = 0;
    for (const s of ATRACCIONES_SEED) {
      const existe = await this.atracciones.exists({ where: { nombre: s.nombre }, withDeleted: true });
      if (existe) continue;
      await this.atracciones.save(
        this.atracciones.create({
          nombre: s.nombre,
          descripcion: s.descripcion,
          duracion: s.duracion,
          precioTicket: s.precio,
          moneda: 'USD',
          tipoProducto: ProductType[s.tipo],
          cancelacionGratuita: s.cancelacionGratuita,
          categorias: s.categorias,
          insignias: s.insignias,
          incluye: s.incluye,
          idiomas: s.idiomas,
          horarios: s.horarios,
          cupoDiario: 20,
          puntuacion: null,
          numeroResenas: 0,
          estaActivo: true,
          operadorId: s.operadorId,
          ubicaciones: [{
            direccion: s.direccion, ciudadId: s.ciudadId, pais: 'ec',
            latitud: s.latitud, longitud: s.longitud, tipo: 'punto_de_encuentro',
          }] as any,
          fotos: s.fotos.map((url, orden) => ({ url, orden })) as any,
        }),
      );
      nuevas++;
    }
    this.logger.log(`Atracciones de ejemplo: ${ATRACCIONES_SEED.length} en el catálogo inicial (nuevas: ${nuevas})`);
  }
}
